-- Курс 95: SMM с нуля. Объединяет темы 8 бесплатных курсов из подборки SMMplanner в одну программу с практикой. Цена 4,99 ₽.
INSERT INTO t_p78828167_tutor_platform_1.course_curricula (course_id,course_title,subject,grade_band,total_lessons,total_modules,estimated_hours,program_description,learning_outcomes,target_audience,prerequisites,methodology,final_project,certificate_available,generated_by,version,is_fallback,age_rating) VALUES (95,'SMM с нуля: продвижение в соцсетях с ИИ — от стратегии до первых клиентов','smm','adult',48,8,26,'Полная программа SMM-специалиста в одном курсе: интернет-маркетинг и целевая аудитория, контент-стратегия, ВКонтакте и Telegram, таргетированная реклама VK Реклама, дизайн для соцсетей без дизайнера, нейросети в SMM, аналитика и отчёты для заказчика. Каждый модуль заканчивается практикой на реальном или учебном проекте. В финале — собственная SMM-стратегия, портфолио и план выхода на первых клиентов.','["Определяете целевую аудиторию и анализируете конкурентов", "Составляете SMM-стратегию и контент-план на месяц", "Ведёте сообщество ВКонтакте и Telegram-канал", "Запускаете и анализируете таргетированную рекламу в VK Реклама", "Делаете обложки, посты и сторис без дизайнера", "Используете нейросети для текстов, идей и картинок", "Считаете метрики и готовите отчёт для заказчика", "Собираете портфолио и находите первых клиентов"]'::jsonb,'Новички без опыта, предприниматели, которые сами ведут соцсети, фрилансеры и все, кто хочет освоить профессию SMM-специалиста.','["опыт в маркетинге не требуется", "уверенная работа с компьютером и смартфоном", "аккаунт ВКонтакте и Telegram"]'::jsonb,'Учимся на практике: в каждом модуле — задание на собственном или учебном проекте. Теория — короткими уроками по делу. ИИ-наставник 24/7 объясняет, проверяет задания и помогает с контентом.','Итоговый проект: SMM-стратегия для реального бизнеса — анализ аудитории, контент-план на месяц, рекламная кампания и отчёт по метрикам.',true,'editorial_manual',1,false,'18+');

